'use strict';
window.factoryTutorial=api=>{
 const $=s=>document.querySelector(s),targets=[['splitter',3,3,0],['belt',3,4,0],['plank',4,4,0],['belt',5,4,0],['belt',6,4,3]],arrow=['↘','↙','↖','↗'];let data=null,lastMarkup='',lastStep=-1,message='',hint=false;
 const steps=[
  ['Meet your factory','Select the plank workshop on the highlighted tile. Use ⓘ to inspect its recipe and rate. The extractor can supply 24 logs/min, the workshop makes 12 planks/min, and belts can carry 120 items/min.'],
  ['Predict the bottleneck','Each plank needs 1 log. What is the greatest sustained output of this line, in planks per minute?',12,'Compare 24, 12 and 120. The smallest capacity limits the whole line. min(24, 12, 120) = 12.'],
  ['Measure before changing','Press Run factory. Collect 60 simulation seconds of evidence, using 4× speed if you want. The flow overlay shows actual output / rated capacity. Compare the workshop with the backed-up raw-material line.'],
  ['Calculate the workshop count','Our target is 24 planks/min. Each workshop makes 12. How many supplied workshops do we need in total?',2,'Required workshops = target ÷ rate per workshop = 24 ÷ 12 = 2.'],
  ['Build a parallel line','Replace the highlighted belt with a splitter. Add a second workshop and connect the highlighted route. Split the 24 logs/min equally: 24 ÷ 2 = 12 for each workshop. Keep the original output line connected.'],
  ['Predict, then test','With two workshops supplied at 12 logs/min each, what total output do you predict? Enter planks per minute, then run another 60 simulation seconds.',24,'Parallel capacities add: 12 + 12 = 24. Our source supplies 24, so both workshops can stay supplied.'],
  ['Count the extra cost','The improvement adds one splitter (12 credits), one workshop (35), and three belts (1 each). Removing the original belt refunds 1. How many extra credits does this design cost?',49,'12 + 35 + (3 × 1) − 1 = 49 extra credits. Refunds matter when comparing designs.'],
  ['Calculate the percentage gain','We raised sustained output from 12 to 24 planks/min. What is the percentage increase?',100,'Increase = 24 − 12 = 12. Percentage increase = (12 ÷ original 12) × 100 = 100%.'],
  ['Take the method into your game','You predicted 12/min, found the bottleneck, built two parallel workshops, and measured 24/min. The design costs 49 extra credits for a 100% output increase. In your next mission: calculate → build → measure → explain → improve.']
 ];
 function active(){return api.get().level.id==='tutorial';}
 function missing(){return targets.filter(([type,x,y,dir])=>{const c=api.get().cells.get(`${x},${y}`);return c?.type!==type||c.dir!==dir;});}
 function persist(){if(!active()||!data)return;api.team().tutorial={step:data.step,answers:{...data.answers},baseline:data.baseline,improved:data.improved,cells:api.construction()};api.save();}
 function intro(){const saved=api.team().tutorial;api.open(`${api.heading('GUIDED PRACTICE','Use maths to improve a factory')}<p>Work together to predict, find a bottleneck, build a parallel line, and check the result with real measurements.</p><div class="briefing"><b>Your practice challenge</b><p>A source supplies 24 logs/min, but one workshop can process only 12. Can you double the output without buying unnecessary machines?</p></div><p>Practice has its own board and construction credits. It does not spend stars or change your mission layout.</p><div class="math-actions">${saved?'<button class="primary" data-tutorial-resume>Resume tutorial</button>':''}<button ${saved?'':'class="primary"'} data-tutorial-start>Start from the beginning</button><button data-tutorial-cancel>Return</button></div>${api.team().tutorialComplete?'<p class="small-note">Your team has completed this tutorial. You can replay it.</p>':''}`);}
 function start(resume){const saved=resume?api.team().tutorial:null;data={step:Number.isInteger(saved?.step)?Math.max(0,Math.min(8,saved.step)):0,answers:Object.fromEntries(Object.entries(saved?.answers||{}).filter(([k,n])=>Number.isInteger(Number(k))&&steps[Number(k)]?.[2]!==undefined&&n===steps[Number(k)][2])),baseline:Number(saved?.baseline)||0,improved:Number(saved?.improved)||0,measureStart:0};message='';hint=false;lastMarkup='';lastStep=-1;api.start(saved?.cells);document.body.classList.add('tutorial-active');for(const id of ['teams','shop','restart','revise'])$('#'+id).disabled=true;$('#tutorial-panel').hidden=false;api.enableFlow();persist();update();}
 function ready(){const s=api.get();if(data.step===0)return s.selected&&s.cells.get(s.selected)?.type==='plank';if(data.step===2||data.step===5)return s.time-data.measureStart>=60&&api.rate()>=(data.step===2?10:22)&&(data.step!==5||data.answers[5]===24);if(data.step===4)return !missing().length;return steps[data.step][2]!==undefined?data.answers[data.step]===steps[data.step][2]:true;}
 function advance(){if(!ready()){message='Complete this step first. Try the hint if you need help.';update();return;}if(data.step===2)data.baseline=api.rate();if(data.step===5)data.improved=api.rate();if(data.step===8){api.team().tutorialComplete=true;persist();exit();return;}data.step++;data.measureStart=api.get().time;message='';hint=false;lastMarkup='';persist();update();}
 function exit(){persist();document.body.classList.remove('tutorial-active');$('#tutorial-panel').hidden=true;for(const id of ['teams','shop','restart','revise'])$('#'+id).disabled=false;api.exit();data=null;lastMarkup='';}
 function update(){if(!active()||!data)return;const [title,body,answer,help]=steps[data.step],s=api.get(),measuring=data.step===2||data.step===5,done=ready(),markup=`<span class="eyebrow">MATHS TUTORIAL · ${data.step+1} / ${steps.length}</span><div class="tutorial-progress" aria-label="Step ${data.step+1} of ${steps.length}"><span style="width:${(data.step+1)/steps.length*100}%"></span></div><h2>${title}</h2><p>${body}</p>${answer!==undefined?`<label for="tutorial-answer">Your answer ${data.step===7?'(%)':data.step===3?'(workshops)':data.step===6?'(credits)':'(planks/min)'}</label><input id="tutorial-answer" inputmode="decimal" maxlength="8" value="${data.answers[data.step]??''}"><div class="tutorial-keypad">${['1','2','3','4','5','6','7','8','9','⌫','0','.'].map(k=>`<button data-tutorial-key="${k}">${k}</button>`).join('')}</div><button class="primary" data-tutorial-check>Check my calculation</button>`:''}${measuring?`<div class="tutorial-measure"><b>${Math.min(60,Math.floor(s.time-data.measureStart))} / 60 simulation seconds</b><br>Measured delivery: <strong>${api.rate().toFixed(1)} / min</strong>${data.step===5?`<br>Before: ${data.baseline.toFixed(1)} / min`:''}<p>${s.running?'Factory running.': 'Tap Run factory to collect evidence.'}</p></div>`:''}${data.step===4?`<ol class="tutorial-build-list">${targets.map(([t,x,y,d])=>`<li class="${missing().some(p=>p[1]===x&&p[2]===y)?'':'done'}">${t==='plank'?'Plank workshop':t==='splitter'?'Splitter':'Belt'} · column ${x+1}, row ${y+1} · ${arrow[d]}</li>`).join('')}</ol><button data-tutorial-demo>Show one next build</button>`:''}${data.step===8?`<div class="tutorial-measure">Before: <b>${data.baseline.toFixed(1)} / min</b><br>After: <b>${data.improved.toFixed(1)} / min</b><br>Reference improvement: +49 credits · +100%<br>Your layout: ${s.level.budget-s.budget} credits</div>`:''}<p id="tutorial-feedback" role="status">${message}</p>${hint?`<div class="feedback">${help|| (data.step===4?'Tap the belt on the highlighted splitter tile and Delete it first. Choose Splitter, place it, then follow the remaining highlighted tiles. Tap an existing piece to rotate it.':'Rates need time to settle: wait for a full 60 simulation seconds and check that the line is connected. Use the Flow overlay to find a blocked output.')}</div>`:''}<div class="tutorial-nav"><button data-tutorial-hint>Hint</button><button class="primary" data-tutorial-next ${done?'':'disabled'}>${data.step===8?'Finish tutorial':'Next step →'}</button></div><button class="tutorial-exit" data-tutorial-exit>Save & leave practice</button>`;
  // Keep the input and caret stable while the simulation draws frames.
  if(markup!==lastMarkup){const input=$('#tutorial-answer'),value=input?.value,focused=document.activeElement===input;$('#tutorial-panel').innerHTML=markup;lastMarkup=markup;if(lastStep===data.step&&value!==undefined&&answer!==undefined&&data.answers[data.step]===undefined)$('#tutorial-answer').value=value;if(focused)$('#tutorial-answer')?.focus();lastStep=data.step;}
 }
 $('#tutorial').onclick=intro;$('#modal').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-tutorial-start'))start(false);if(b.hasAttribute('data-tutorial-resume'))start(true);if(b.hasAttribute('data-tutorial-cancel'))api.cancel();});
 $('#tutorial-panel').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tutorialKey){const input=$('#tutorial-answer'),k=b.dataset.tutorialKey;input.value=k==='⌫'?input.value.slice(0,-1):((k==='.'&&input.value.includes('.'))?input.value:(input.value+k).slice(0,8));}if(b.hasAttribute('data-tutorial-check')){const value=$('#tutorial-answer').value.trim(),n=Number(value);if(value&&Number.isFinite(n)&&n===steps[data.step][2]){data.answers[data.step]=n;message='That matches the calculation. Now test the idea in the factory.';persist();}else{message='Try again. Check the units and use the hint to work through the calculation.';hint=true;}update();}if(b.hasAttribute('data-tutorial-next'))advance();if(b.hasAttribute('data-tutorial-hint')){hint=!hint;update();}if(b.hasAttribute('data-tutorial-demo')){const next=missing()[0];if(next)api.build(...next);update();}if(b.hasAttribute('data-tutorial-exit'))exit();});
 return {active,update,persist,intro,snapshot:()=>active()?{step:data?.step,answers:data?.answers,baseline:data?.baseline,improved:data?.improved,ready:data?!!ready():false,targets:data?.step===4?missing():[]}:null,targets:()=>active()&&data?(data.step===0?[['plank',4,3,0]]:data.step===4?missing():[]):[]};
};
